# Faithful re-implementation of libstdc++ std::sort (introsort) to test the hypothesis.
_S_threshold = 16
def _lg(n):
    r = -1
    while n: n >>= 1; r += 1
    return r
def _move_median_to_first(a, result, i, j, k, comp):
    if comp(a[i], a[j]):
        if comp(a[j], a[k]): a[result], a[j] = a[j], a[result]
        elif comp(a[i], a[k]): a[result], a[k] = a[k], a[result]
        else: a[result], a[i] = a[i], a[result]
    elif comp(a[i], a[k]): a[result], a[i] = a[i], a[result]
    elif comp(a[j], a[k]): a[result], a[k] = a[k], a[result]
    else: a[result], a[j] = a[j], a[result]
def _unguarded_partition(a, first, last, pivot, comp):
    while True:
        while comp(a[first], a[pivot]): first += 1
        last -= 1
        while comp(a[pivot], a[last]): last -= 1
        if not (first < last): return first
        a[first], a[last] = a[last], a[first]
        first += 1
def _unguarded_partition_pivot(a, first, last, comp):
    mid = first + (last - first)//2
    _move_median_to_first(a, first, first+1, mid, last-1, comp)
    return _unguarded_partition(a, first+1, last, first, comp)
def _heap_partial_sort(a, first, last, comp):
    seg = sorted(a[first:last], key=_CmpKey(comp))  # approximation; depth limit rarely hit
    a[first:last] = seg
class _CmpKey:
    def __init__(self, comp): self.comp = comp
    def __call__(self, v):
        comp = self.comp
        class K:
            __slots__=('v',)
            def __init__(s, v): s.v = v
            def __lt__(s, o): return comp(s.v, o.v)
        return K(v)
def _introsort_loop(a, first, last, depth_limit, comp):
    while last - first > _S_threshold:
        if depth_limit == 0:
            _heap_partial_sort(a, first, last, comp); return
        depth_limit -= 1
        cut = _unguarded_partition_pivot(a, first, last, comp)
        _introsort_loop(a, cut, last, depth_limit, comp)
        last = cut
def _unguarded_linear_insert(a, last, comp):
    val = a[last]; nxt = last - 1
    while comp(val, a[nxt]):
        a[last] = a[nxt]; last = nxt; nxt -= 1
    a[last] = val
def _insertion_sort(a, first, last, comp):
    if first == last: return
    for i in range(first+1, last):
        if comp(a[i], a[first]):
            val = a[i]
            a[first+1:i+1] = a[first:i]
            a[first] = val
        else:
            _unguarded_linear_insert(a, i, comp)
def _final_insertion_sort(a, first, last, comp):
    if last - first > _S_threshold:
        _insertion_sort(a, first, first+_S_threshold, comp)
        for i in range(first+_S_threshold, last):
            _unguarded_linear_insert(a, i, comp)
    else:
        _insertion_sort(a, first, last, comp)
def gnu_sort(a, comp):
    if len(a) == 0: return a
    _introsort_loop(a, 0, len(a), _lg(len(a))*2, comp)
    _final_insertion_sort(a, 0, len(a), comp)
    return a
