import sys
SEP = set(b' \n\r\t\v\f\0')
EOS = b'</s>'
def read_words(path):
    data = open(path,'rb').read()
    i = 0; n = len(data); word = bytearray()
    out = []
    while i < n:
        c = data[i]; i += 1
        if c in SEP:
            if not word:
                if c == 0x0a: out.append(bytes(EOS)); continue
                continue
            else:
                if c == 0x0a: i -= 1   # sungetc
                out.append(bytes(word)); word = bytearray(); continue
        word.append(c)
    if word: out.append(bytes(word))
    return out
def build(path, label=b'__label__', minCount=1, minCountLabel=0):
    order = []; cnt = {}; typ = {}
    ntokens = 0
    for w in read_words(path):
        ntokens += 1
        if w not in cnt:
            cnt[w] = 0; order.append(w)
            typ[w] = 1 if w.startswith(label) else 0
        cnt[w] += 1
    entries = [(w, cnt[w], typ[w]) for w in order]
    return entries, ntokens
